using Microsoft.Extensions.ML;
using TicketClassifier.Models;
using TicketClassifier.Services;

var builder = WebApplication.CreateBuilder(args);
builder.Services.AddControllers();
builder.Services.AddSingleton<TicketClassifierService>();

var app = builder.Build();

// Train the model if it doesn't exist
var classifierService = app.Services.GetRequiredService<TicketClassifierService>();
if (!File.Exists(classifierService.ModelPath))
{
    classifierService.Train();
}

// Register PredictionEnginePool after model is available
builder.Services.AddPredictionEnginePool<TicketInput, TicketPrediction>()
    .FromFile(classifierService.ModelPath);

// Rebuild the app with the prediction pool registered
// Since we can't add services after build, restructure:
// We need to register before build. Let's restructure.

app.MapControllers();
app.Run();

